+class ListenerHook : public wxModalDialogHook
+{
+    int Enter(wxDialog* dialog) override
+    {
+        if (dialog == nullptr || !wxIsMainThread())
+            return wxID_NONE;
+        if (int answer = wxID_NONE; dispatch_dialog(*dialog, answer)) {
